"""Импорт банковских выписок.

Поддерживаются три формата (определяются по заголовку):

    nova:        date,amount,description
                 2026-03-01,-350.00,Кофейня Зерно

    sfera:       Дата;Сумма;Описание
                 01.03.2026;-1 200,50;Магазин Лента

    sfera_split: Дата;Описание;Приход;Расход
                 01.03.2026;Зарплата;85 000,00;

Колонки ищутся по названию без учёта регистра и пробелов по краям, лишние
игнорируются. Пустые и «мусорные» строки (из пробелов и разделителей) пропускаются.
Транзакции, уже лежащие в хранилище, не добавляются повторно (см. _import_key).
"""

from __future__ import annotations

import csv
import datetime as dt
import io
import logging
import os
import re
from collections import Counter
from dataclasses import dataclass, replace
from decimal import Decimal
from pathlib import Path
from typing import Iterator

from ledger.clock import Clock, SystemClock
from ledger.errors import StatementError, StatementRowError, UnknownFormatError, ValidationError
from ledger.models import Transaction, parse_amount
from ledger.rules import Categorizer, normalize_text
from ledger.storage import MemoryStore

logger = logging.getLogger(__name__)

# Формат -> (разделитель, {поле -> название колонки в нижнем регистре}).
_FORMATS: dict[str, tuple[str, dict[str, str]]] = {
    "nova": (",", {"date": "date", "amount": "amount", "description": "description"}),
    "sfera": (";", {"date": "дата", "amount": "сумма", "description": "описание"}),
    "sfera_split": (
        ";",
        {"date": "дата", "description": "описание", "income": "приход", "expense": "расход"},
    ),
}

# Сумма «Сферы»: пробелы (в том числе U+00A0) между группами по три цифры, запятая перед копейками.
_RU_AMOUNT = re.compile(r"(?P<sign>[+-]?)(?P<whole>[0-9]{1,3}(?:\s[0-9]{3})+|[0-9]+)(?:,(?P<frac>[0-9]+))?")
_DMY_DATE = re.compile(r"(?P<day>[0-9]{2})\.(?P<month>[0-9]{2})\.(?P<year>[0-9]{4})")
_JUNK_RECORD = re.compile(r"[\s;,]*")


@dataclass(frozen=True)
class RowError:
    line_no: int
    message: str


@dataclass(frozen=True)
class ImportResult:
    format: str
    encoding: str
    added: int
    duplicates: int
    errors: list[RowError]


def normalize_description(text: str) -> str:
    """Описание в виде для сравнения дублей (то же сравнение, что в правилах)."""
    return normalize_text(text)


def import_statement(
    path: str | os.PathLike[str],
    store: MemoryStore,
    *,
    fmt: str | None = None,
    strict: bool = False,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> ImportResult:
    """Импортирует выписку в store.

    Без strict кривые строки попадают в result.errors, остальное импортируется.
    С strict первая кривая строка бросает StatementRowError, и в хранилище ничего не пишется.
    Запись всегда одной пачкой (add_many): либо все добавленные строки, либо ни одной.
    """
    clock = clock or SystemClock()
    imported_at = clock.now()
    text, encoding = _read_text(path)
    name, index, header_line = _detect(text, fmt)
    delimiter = _FORMATS[name][0]

    # Дубли: сравниваем только с тем, что было в хранилище до импорта, по количеству.
    remaining = Counter(_import_key(tx) for tx in store.all())
    to_add: list[Transaction] = []
    errors: list[RowError] = []
    duplicates = 0
    rows = (rec for rec in _records(text, delimiter) if not _is_junk(rec[2]))
    next(rows)  # заголовок уже разобран в _detect
    for line_no, cells, _ in rows:
        try:
            tx = _build(name, cells, index, imported_at)
        except ValidationError as exc:
            if strict:
                raise StatementRowError(str(exc), line_no=line_no) from exc
            errors.append(RowError(line_no, str(exc)))
            continue
        if categorizer is not None:
            category = categorizer.categorize(tx)
            if category is not None:
                tx = replace(tx, category=category)
        key = _import_key(tx)
        if remaining[key] > 0:
            remaining[key] -= 1
            duplicates += 1
            continue
        to_add.append(tx)

    if to_add:
        store.add_many(to_add)
    logger.info("imported %d transactions from %s (duplicates: %d)", len(to_add), path, duplicates)
    return ImportResult(
        format=name,
        encoding=encoding,
        added=len(to_add),
        duplicates=duplicates,
        errors=errors,
    )


def detect_format(path: str | os.PathLike[str]) -> str:
    """Возвращает "nova", "sfera" или "sfera_split" по заголовку файла."""
    text, _ = _read_text(path)
    return _detect(text, None)[0]


def import_csv(
    path: str | os.PathLike[str],
    store: MemoryStore,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> int:
    """Импортирует выписку «Новы» в store и возвращает число добавленных транзакций.

    Обёртка над import_statement(fmt="nova", strict=True) для совместимости.
    """
    result = import_statement(
        path, store, fmt="nova", strict=True, categorizer=categorizer, clock=clock
    )
    return result.added


def _import_key(tx: Transaction) -> tuple[dt.date, Decimal, str]:
    return (tx.date, tx.amount, normalize_description(tx.description))


def _read_text(path: str | os.PathLike[str]) -> tuple[str, str]:
    """Читает файл целиком: UTF-8 (BOM допустим), иначе cp1251."""
    raw = Path(path).read_bytes()
    try:
        return raw.decode("utf-8-sig"), "utf-8"
    except UnicodeDecodeError:
        pass
    try:
        return raw.decode("cp1251"), "cp1251"
    except UnicodeDecodeError as exc:
        raise StatementError(f"cannot decode {path}: neither utf-8 nor cp1251") from exc


def _records(text: str, delimiter: str) -> Iterator[tuple[int, list[str], str]]:
    """CSV-записи: (номер первой физической строки, ячейки, сырой текст записи)."""
    pending: list[str] = []

    def lines() -> Iterator[str]:
        for line in io.StringIO(text, newline=""):
            pending.append(line)
            yield line

    start = 1
    try:
        for cells in csv.reader(lines(), delimiter=delimiter):
            count = len(pending)
            raw = "".join(pending)
            pending.clear()
            yield start, cells, raw
            start += count
    except csv.Error as exc:
        raise StatementError(str(exc), line_no=start) from exc


def _is_junk(raw: str) -> bool:
    """Пустая строка, строка из пробелов или из одних разделителей."""
    return _JUNK_RECORD.fullmatch(raw) is not None


def _detect(text: str, fmt: str | None) -> tuple[str, dict[str, int], int | None]:
    """Определяет формат: (имя, {поле -> индекс колонки}, строка заголовка или None)."""
    if fmt is not None and fmt not in _FORMATS:
        raise UnknownFormatError(f"unknown format {fmt!r}")
    candidates = [fmt] if fmt is not None else list(_FORMATS)
    found: list[tuple[str, dict[str, int]]] = []
    header_line: int | None = None
    for name in candidates:
        delimiter, columns = _FORMATS[name]
        header = next(((ln, cells) for ln, cells, raw in _records(text, delimiter) if not _is_junk(raw)), None)
        if header is None:
            continue
        header_line = header[0]
        index = _match_columns(header[1], columns)
        if index is not None:
            found.append((name, index))

    if len(found) == 1:
        name, index = found[0]
        return name, index, header_line
    if fmt is not None:
        raise UnknownFormatError(f"header does not match format {fmt!r}", line_no=header_line)
    if not found:
        raise UnknownFormatError("unrecognized header", line_no=header_line)
    names = ", ".join(name for name, _ in found)
    raise UnknownFormatError(f"ambiguous header, matches: {names}", line_no=header_line)


def _match_columns(header: list[str], columns: dict[str, str]) -> dict[str, int] | None:
    names = [cell.strip().casefold() for cell in header]
    index: dict[str, int] = {}
    for key, column in columns.items():
        positions = [pos for pos, name in enumerate(names) if name == column]
        if len(positions) != 1:
            return None
        index[key] = positions[0]
    return index


def _build(name: str, cells: list[str], index: dict[str, int], imported_at: dt.datetime) -> Transaction:
    """Собирает Transaction из ячеек строки; ValidationError — ошибка строки."""

    def cell(key: str) -> str:
        pos = index[key]
        if pos >= len(cells):
            raise ValidationError("not enough fields")
        return cells[pos]

    if name == "nova":
        date = _iso_date(cell("date"))
        amount = parse_amount(cell("amount"))
    elif name == "sfera":
        date = _dmy_date(cell("date"))
        sign, value = _parse_ru_amount(cell("amount"))
        amount = -value if sign == "-" else value
    else:
        date = _dmy_date(cell("date"))
        amount = _split_amount(cell("income"), cell("expense"))
    return Transaction(
        date=date,
        amount=amount,
        description=cell("description").strip(),
        imported_at=imported_at,
    )


def _iso_date(text: str) -> dt.date:
    try:
        return dt.date.fromisoformat(text.strip())
    except ValueError as exc:
        raise ValidationError(f"invalid date {text!r}") from exc


def _dmy_date(text: str) -> dt.date:
    match = _DMY_DATE.fullmatch(text.strip())
    if match is None:
        raise ValidationError(f"invalid date {text!r}, expected DD.MM.YYYY")
    try:
        return dt.date(int(match["year"]), int(match["month"]), int(match["day"]))
    except ValueError as exc:
        raise ValidationError(f"invalid date {text!r}") from exc


def _parse_ru_amount(text: str) -> tuple[str, Decimal]:
    """'-1 234,50' -> ('-', Decimal('1234.50')). Знак возвращается отдельно, значение без знака."""
    match = _RU_AMOUNT.fullmatch(text.strip())
    if match is None:
        raise ValidationError(f"invalid amount: {text!r}")
    frac = match["frac"] or ""
    if len(frac) > 2:
        raise ValidationError(f"amount has more than 2 decimal places: {text!r}")
    whole = re.sub(r"\s", "", match["whole"])
    return match["sign"], Decimal(f"{whole}.{frac or '0'}")


def _split_amount(income: str, expense: str) -> Decimal:
    """Формат sfera_split: суммы без знака, заполнена ровно одна колонка; 0,00 — как пусто."""
    filled: list[Decimal] = []
    for text, is_income in ((income, True), (expense, False)):
        if not text.strip():
            continue
        sign, value = _parse_ru_amount(text)
        if sign:
            raise ValidationError(f"sign is not allowed in Приход/Расход: {text!r}")
        if value == 0:
            continue
        filled.append(value if is_income else -value)
    if len(filled) != 1:
        raise ValidationError("exactly one of Приход/Расход must be filled")
    return filled[0]

"""Хранилища транзакций.

MemoryStore держит всё в памяти, JsonFileStore дополнительно сохраняет
состояние в JSON-файл после каждого изменения (атомарно, через временный файл).
"""

from __future__ import annotations

import json
import logging
import os
import tempfile
from dataclasses import replace
from pathlib import Path
from typing import Iterable

from ledger.errors import StorageError
from ledger.models import Transaction

logger = logging.getLogger(__name__)


class MemoryStore:
    """Хранилище в памяти."""

    def __init__(self) -> None:
        self._items: list[Transaction] = []
        self._next_id = 1

    def all(self) -> list[Transaction]:
        return list(self._items)

    def get(self, tx_id: int) -> Transaction:
        for tx in self._items:
            if tx.id == tx_id:
                return tx
        raise StorageError(f"transaction {tx_id} not found")

    def add(self, tx: Transaction) -> Transaction:
        """Добавляет одну транзакцию и возвращает её с назначенным id."""
        return self.add_many([tx])[0]

    def add_many(self, txs: Iterable[Transaction]) -> list[Transaction]:
        """Добавляет пачку транзакций целиком: либо все, либо ни одной."""
        batch = list(txs)
        for tx in batch:
            if not isinstance(tx, Transaction):
                raise StorageError(f"not a Transaction: {tx!r}")
            if tx.id is not None:
                raise StorageError(f"transaction already has id {tx.id}")
        stored = []
        next_id = self._next_id
        for tx in batch:
            stored.append(replace(tx, id=next_id))
            next_id += 1
        self._commit(self._items + stored, next_id)
        logger.debug("added %d transactions", len(stored))
        return stored

    def update_category(self, tx_id: int, category: str | None) -> Transaction:
        items = []
        updated = None
        for tx in self._items:
            if tx.id == tx_id:
                updated = replace(tx, category=category)
                items.append(updated)
            else:
                items.append(tx)
        if updated is None:
            raise StorageError(f"transaction {tx_id} not found")
        self._commit(items, self._next_id)
        return updated

    def _commit(self, items: list[Transaction], next_id: int) -> None:
        self._items = items
        self._next_id = next_id


class JsonFileStore(MemoryStore):
    """Хранилище в JSON-файле. Файл создаётся при первой записи."""

    def __init__(self, path: str | os.PathLike[str]) -> None:
        super().__init__()
        self.path = Path(path)
        if self.path.exists():
            self._load()

    def _load(self) -> None:
        try:
            data = json.loads(self.path.read_text(encoding="utf-8"))
            self._items = [Transaction.from_dict(d) for d in data["transactions"]]
            self._next_id = int(data["next_id"])
        except (OSError, ValueError, KeyError, TypeError) as exc:
            raise StorageError(f"cannot read {self.path}: {exc}") from exc
        logger.debug("loaded %d transactions from %s", len(self._items), self.path)

    def _commit(self, items: list[Transaction], next_id: int) -> None:
        payload = {
            "next_id": next_id,
            "transactions": [tx.to_dict() for tx in items],
        }
        text = json.dumps(payload, ensure_ascii=False, indent=2)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=self.path.parent, prefix=".ledger-", suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                fh.write(text)
            os.replace(tmp, self.path)
        except OSError as exc:
            try:
                os.unlink(tmp)
            except OSError:
                pass
            raise StorageError(f"cannot write {self.path}: {exc}") from exc
        super()._commit(items, next_id)

"""Модели предметной области и денежные суммы.

Все суммы в проекте — Decimal с двумя знаками после запятой.
"""

from __future__ import annotations

import datetime as dt
import re
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation
from typing import Any

from ledger.errors import ValidationError

UNCATEGORIZED = "uncategorized"

CENT = Decimal("0.01")

_PLAIN_AMOUNT = re.compile(r"^[+-]?\d+(\.\d{1,2})?$")


def to_money(value: Decimal) -> Decimal:
    """Проверяет сумму и приводит её к двум знакам после запятой.

    Принимает только Decimal: float и int-строки сюда попадать не должны.
    Больше двух значащих знаков после запятой — ошибка, а не округление.
    """
    if not isinstance(value, Decimal):
        raise ValidationError(f"amount must be Decimal, got {type(value).__name__}")
    if not value.is_finite():
        raise ValidationError(f"amount must be finite, got {value}")
    quantized = value.quantize(CENT)
    if quantized != value:
        raise ValidationError(f"amount has more than 2 decimal places: {value}")
    return quantized


def parse_amount(text: str) -> Decimal:
    """Разбирает сумму вида '-1234.50' (точка, без разделителей тысяч)."""
    cleaned = text.strip()
    if not _PLAIN_AMOUNT.match(cleaned):
        raise ValidationError(f"invalid amount: {text!r}")
    try:
        return to_money(Decimal(cleaned))
    except InvalidOperation as exc:  # pragma: no cover - регулярка уже отсекла мусор
        raise ValidationError(f"invalid amount: {text!r}") from exc


def format_amount(amount: Decimal) -> str:
    """Форматирует сумму для людей: '-1 234.50'."""
    sign = "-" if amount < 0 else ""
    whole, frac = f"{abs(amount):.2f}".split(".")
    groups = []
    while whole:
        groups.insert(0, whole[-3:])
        whole = whole[:-3]
    return f"{sign}{' '.join(groups)}.{frac}"


@dataclass(frozen=True)
class Transaction:
    """Одна операция по счёту.

    amount < 0 — расход, amount > 0 — приход. Идентификатор назначает хранилище.
    """

    date: dt.date
    amount: Decimal
    description: str
    category: str | None = None
    imported_at: dt.datetime | None = None
    id: int | None = None

    def __post_init__(self) -> None:
        if not isinstance(self.date, dt.date) or isinstance(self.date, dt.datetime):
            raise ValidationError(f"date must be datetime.date, got {self.date!r}")
        amount = to_money(self.amount)
        if amount == 0:
            raise ValidationError("amount must be non-zero")
        object.__setattr__(self, "amount", amount)
        if not isinstance(self.description, str) or not self.description.strip():
            raise ValidationError("description must be a non-empty string")
        if self.category is not None and not self.category.strip():
            raise ValidationError("category must be None or a non-empty string")

    @property
    def is_expense(self) -> bool:
        return self.amount < 0

    @property
    def month(self) -> tuple[int, int]:
        return (self.date.year, self.date.month)

    def to_dict(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "date": self.date.isoformat(),
            "amount": str(self.amount),
            "description": self.description,
            "category": self.category,
            "imported_at": self.imported_at.isoformat() if self.imported_at else None,
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> "Transaction":
        imported_at = data.get("imported_at")
        return cls(
            id=data.get("id"),
            date=dt.date.fromisoformat(data["date"]),
            amount=Decimal(data["amount"]),
            description=data["description"],
            category=data.get("category"),
            imported_at=dt.datetime.fromisoformat(imported_at) if imported_at else None,
        )

